package com.hotel.hotelproject.controller;
import com.hotel.hotelproject.dto.*; import com.hotel.hotelproject.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api") @RequiredArgsConstructor
public class HotelController {
 private final RoomTypeService roomTypes; private final RoomService rooms; private final EmployeeService employees; private final GuestService guests; private final ReservationService reservations; private final PaymentService payments;
 @GetMapping("/room-types") public List<RoomTypeDTO> roomTypes(){return roomTypes.findAll();} @GetMapping("/room-types/{id}") public RoomTypeDTO roomType(@PathVariable Long id){return roomTypes.findById(id);} @PostMapping("/room-types") public ResponseEntity<RoomTypeDTO> createRoomType(@Valid @RequestBody RoomTypeDTO d){return created(roomTypes.save(d));} @PutMapping("/room-types/{id}") public RoomTypeDTO updateRoomType(@PathVariable Long id,@Valid @RequestBody RoomTypeDTO d){return roomTypes.save(new RoomTypeDTO(id,d.name(),d.nightlyRate(),d.description()));} @DeleteMapping("/room-types/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteRoomType(@PathVariable Long id){roomTypes.delete(id);}
 @GetMapping("/rooms") public List<RoomDTO> rooms(){return rooms.findAll();} @GetMapping("/rooms/available") public List<RoomDTO> available(@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut){return rooms.findAvailable(checkIn,checkOut);} @GetMapping("/rooms/{id}") public RoomDTO room(@PathVariable Long id){return rooms.findById(id);} @PostMapping("/rooms") public ResponseEntity<RoomDTO> createRoom(@Valid @RequestBody RoomDTO d){return created(rooms.save(d));} @PutMapping("/rooms/{id}") public RoomDTO updateRoom(@PathVariable Long id,@Valid @RequestBody RoomDTO d){return rooms.save(new RoomDTO(id,d.number(),d.status(),d.roomTypeId(),d.assignedEmployeeId()));} @PatchMapping("/rooms/{id}/assign-employee/{employeeId}") public RoomDTO assignEmployee(@PathVariable Long id,@PathVariable Long employeeId){return rooms.assignEmployee(id,employeeId);} @DeleteMapping("/rooms/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteRoom(@PathVariable Long id){rooms.delete(id);}
 @GetMapping("/employees") public List<EmployeeDTO> employees(){return employees.findAll();} @GetMapping("/employees/{id}") public EmployeeDTO employee(@PathVariable Long id){return employees.findById(id);} @GetMapping("/employees/{id}/rooms") public List<RoomDTO> employeeRooms(@PathVariable Long id){return employees.rooms(id);} @PostMapping("/employees") public ResponseEntity<EmployeeDTO> createEmployee(@Valid @RequestBody EmployeeDTO d){return created(employees.save(d));} @PutMapping("/employees/{id}") public EmployeeDTO updateEmployee(@PathVariable Long id,@Valid @RequestBody EmployeeDTO d){return employees.save(new EmployeeDTO(id,d.name(),d.email(),d.role()));} @DeleteMapping("/employees/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteEmployee(@PathVariable Long id){employees.delete(id);}
 @GetMapping("/guests") public List<GuestDTO> guests(){return guests.findAll();} @GetMapping("/guests/{id}") public GuestDTO guest(@PathVariable Long id){return guests.findById(id);} @PostMapping("/guests") public ResponseEntity<GuestDTO> createGuest(@Valid @RequestBody GuestDTO d){return created(guests.save(d));} @PutMapping("/guests/{id}") public GuestDTO updateGuest(@PathVariable Long id,@Valid @RequestBody GuestDTO d){return guests.save(new GuestDTO(id,d.name(),d.email(),d.phone()));} @DeleteMapping("/guests/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteGuest(@PathVariable Long id){guests.delete(id);}
 @GetMapping("/reservations") public List<ReservationDTO> reservations(){return reservations.findAll();} @GetMapping("/reservations/guest/{guestId}") public List<ReservationDTO> guestReservations(@PathVariable Long guestId){return reservations.byGuest(guestId);} @GetMapping("/reservations/{id}") public ReservationDTO reservation(@PathVariable Long id){return reservations.findById(id);} @GetMapping("/reservations/{id}/payment") public PaymentDTO reservationPayment(@PathVariable Long id){return payments.byReservation(id);} @PostMapping("/reservations") public ResponseEntity<ReservationDTO> createReservation(@Valid @RequestBody ReservationDTO d){return created(reservations.save(d));} @PutMapping("/reservations/{id}") public ReservationDTO updateReservation(@PathVariable Long id,@Valid @RequestBody ReservationDTO d){return reservations.save(new ReservationDTO(id,d.checkIn(),d.checkOut(),d.status(),d.roomId(),d.guestId()));} @PatchMapping("/reservations/{id}/cancel") public ReservationDTO cancelReservation(@PathVariable Long id){return reservations.cancel(id);} @DeleteMapping("/reservations/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteReservation(@PathVariable Long id){reservations.delete(id);}
 @GetMapping("/payments") public List<PaymentDTO> payments(){return payments.findAll();} @GetMapping("/payments/{id}") public PaymentDTO payment(@PathVariable Long id){return payments.findById(id);} @PostMapping("/payments") public ResponseEntity<PaymentDTO> createPayment(@Valid @RequestBody PaymentDTO d){return created(payments.save(d));} @PutMapping("/payments/{id}") public PaymentDTO updatePayment(@PathVariable Long id,@Valid @RequestBody PaymentDTO d){return payments.save(new PaymentDTO(id,d.amount(),d.status(),d.method(),d.paidAt(),d.reservationId()));} @DeleteMapping("/payments/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deletePayment(@PathVariable Long id){payments.delete(id);}
 private <T> ResponseEntity<T> created(T body){return ResponseEntity.status(HttpStatus.CREATED).body(body);}
}